'use strict';
let gripPresets=[];
$('interactionScale').closest('label').after(Object.assign(document.createElement('details'),{id:'gripPresetTools',innerHTML:'<summary>Saved grips</summary><input id="gripPresetName" maxlength="80" placeholder="e.g. Phone in right hand" aria-label="Grip name"><button id="saveGripPreset">Save current grip</button><select id="gripPresetChoice" aria-label="Saved grip"></select><button id="useGripPreset">Apply grip settings</button><button id="removeGripPreset">Remove saved grip</button>'}));
function gripSettings(){return{hand:$('interactionHand').value,offset:{x:+$('interactionOffsetX').value||0,y:+$('interactionOffsetY').value||0},rotation:+$('interactionRotation').value||0,scale:+$('interactionScale').value||1,followRotation:$('interactionFollowRotation').checked}}
function validGrip(p){return p&&typeof p.id==='string'&&typeof p.name==='string'&&p.name.length<=80&&['left','right'].includes(p.hand)&&p.offset&&['x','y'].every(k=>Number.isFinite(p.offset[k])&&Math.abs(p.offset[k])<=200)&&Number.isFinite(p.rotation)&&Math.abs(p.rotation)<=360&&Number.isFinite(p.scale)&&p.scale>=.05&&p.scale<=10&&typeof p.followRotation==='boolean'}
function renderGripPresets(){const select=$('gripPresetChoice'),old=select.value;select.replaceChildren();for(const p of gripPresets){const option=document.createElement('option');option.value=p.id;option.textContent=p.name;select.append(option)}if(gripPresets.some(p=>p.id===old))select.value=old}
$('saveGripPreset').onclick=async()=>{try{if(gripPresets.length>=30)throw Error('Keep up to 30 saved grips.');const name=$('gripPresetName').value.trim();if(!name)throw Error('Name this grip first.');const preset={id:uid(),name,...gripSettings()};if(!validGrip(preset))throw Error('Check the grip offsets and size.');const next=[...gripPresets,preset];await workspacePut('gripPresets',next);gripPresets=next;renderGripPresets();toast('Grip saved for reuse.')}catch(e){toast(e.message)}};$('useGripPreset').onclick=()=>{const p=gripPresets.find(p=>p.id===$('gripPresetChoice').value);if(!p)return;$('interactionHand').value=p.hand;$('interactionOffsetX').value=p.offset.x;$('interactionOffsetY').value=p.offset.y;$('interactionRotation').value=p.rotation;$('interactionScale').value=p.scale;$('interactionFollowRotation').checked=p.followRotation;toast('Grip settings loaded. Add the interaction to use them.')};$('removeGripPreset').onclick=async()=>{try{const next=gripPresets.filter(p=>p.id!==$('gripPresetChoice').value);await workspacePut('gripPresets',next);gripPresets=next;renderGripPresets()}catch{toast('Could not update saved grips.')}};workspaceValue('gripPresets').then(list=>{gripPresets=Array.isArray(list)?list.filter(validGrip).slice(0,30):[];renderGripPresets()}).catch(()=>{});
for(const[value,label]of [['ease-in','Ease in'],['ease-out','Ease out'],['bounce','Bounce'],['cubic','Custom curve']]){const option=document.createElement('option');option.value=value;option.textContent=label;$('objectPartEase').append(option)}
$('objectPartEase').closest('label').after(Object.assign(document.createElement('details'),{id:'partCurveControls',innerHTML:'<summary>Custom timing curve</summary><div class="rig-tools"><label>X1<input id="partCurveX1" type="number" min="0" max="1" step="0.05" value="0.25"></label><label>Y1<input id="partCurveY1" type="number" min="-2" max="3" step="0.05" value="0.1"></label><label>X2<input id="partCurveX2" type="number" min="0" max="1" step="0.05" value="0.25"></label><label>Y2<input id="partCurveY2" type="number" min="-2" max="3" step="0.05" value="1"></label></div><canvas id="partCurveCanvas" width="300" height="150"></canvas><button id="applyPartCurve">Apply to key here</button><p class="note">Each key controls the segment after it. Overshoot stays inside the part’s value limits.</p>'}));
function paintPartCurve(){const c=$('partCurveCanvas'),g=c.getContext('2d'),curve=['partCurveX1','partCurveY1','partCurveX2','partCurveY2'].map(id=>+$(id).value);g.clearRect(0,0,300,150);g.strokeStyle='#b69bff';g.lineWidth=2;g.beginPath();for(let i=0;i<=100;i++){const f=i/100,x=15+270*f,y=135-120*clamp(easingAt({ease:'cubic',curve},f),0,1);i?g.lineTo(x,y):g.moveTo(x,y)}g.stroke()}
$('applyPartCurve').onclick=()=>{const o=partEditorObject(),key=o?.objectAnimation?.[partEditorField]?.find(k=>Math.abs(k.t-time)<.015);if(!key||o.locked)return toast('Select an unlocked object-part key first.');const curve=['partCurveX1','partCurveY1','partCurveX2','partCurveY2'].map(id=>+$(id).value);if(!curve.every(Number.isFinite)||curve[0]<0||curve[0]>1||curve[2]<0||curve[2]>1||curve[1]<-2||curve[1]>3||curve[3]<-2||curve[3]>3)return toast('Keep timing control points inside the displayed limits.');key.ease='cubic';key.curve=curve;$('objectPartEase').value='cubic';save();paintObjectParts();paintPartCurve()};
for(const id of ['partCurveX1','partCurveY1','partCurveX2','partCurveY2'])$(id).oninput=paintPartCurve;const partsBeforeCurve=renderObjectPartControls;renderObjectPartControls=function(){partsBeforeCurve();const key=partEditorObject()?.objectAnimation?.[partEditorField]?.find(k=>Math.abs(k.t-time)<.015),curve=key?.curve||[.25,.1,.25,1];for(const[id,i]of [['partCurveX1',0],['partCurveY1',1],['partCurveX2',2],['partCurveY2',3]])$(id).value=curve[i];paintPartCurve()};
